#!/usr/bin/env bash
set -euo pipefail

echo "=========================================================="
echo " AI Gym Cloud - GitHub Codespace Source Code Installer"
echo " Target Repository: https://github.com/aza610aza01-creator/fyptest.git"
echo "=========================================================="

# Extract all 58 project files into the current directory
base64 -d << 'EOF_PAYLOAD' | tar -xzf -

EOF_PAYLOAD

echo "[1/3] Extracted all AI Gym Cloud source files (lib/, supabase/, test/, android/, .devcontainer/, setup.ps1, README.md)."

if [ ! -d ".git" ]; then
  git init
  git branch -M main
fi

if ! git remote | grep -q "^origin$"; then
  git remote add origin https://github.com/aza610aza01-creator/fyptest.git
else
  git remote set-url origin https://github.com/aza610aza01-creator/fyptest.git
fi

echo "[2/3] Staging and committing all project files..."
git add .
git commit -m "Add complete AI Gym Cloud Flutter Android & Supabase project" || true

echo "[3/3] Pushing to origin main (https://github.com/aza610aza01-creator/fyptest.git)..."
git push -u origin main

echo "=========================================================="
echo " Done! All AI Gym Cloud files are now in your Codespace and pushed to GitHub."
echo "=========================================================="